97:  * One draw of history's shadow: uniform in the centre plus or minus the half-width, clamped to 0..1000. A cited
98:  * direction draws around its permille centre with the pack's spread; an unknown stat around the unknown centre with the
99:  * wider unknown spread. Each stat takes one draw from the stream, in every mode (a zero width still draws).
100:  */
101: export function drawStat(rules: ShadowRules, centre: StatCentre, mode: ShadowMode, stream: RngStream): number {
102:   const isKnown = mode !== 'unknown-men' && centre.direction !== null;
103:   const mid = isKnown ? rules.centrePermille[centre.direction!] : rules.unknownCentre;
104:   const half = mode === 'as-history' ? 0 : isKnown ? rules.spread : rules.unknownSpread;
105:   return clampPermille(mid - half + nextInt(stream, 2 * half + 1));
106: }
