118: export function initialPeople(map: WorldIndex, start: ScenarioStart, seed: number, mode: ShadowMode): PeopleStart {
119:   const rules = map.world.rules.people.shadow;
120:   const principals = new Map(start.factions.filter((f) => f.principal !== null).map((f) => [f.faction, f.principal!]));
121:   const personTrue: Record<PersonId, PersonTrue> = {};
122:   const personTraits: Record<PersonId, readonly string[]> = {};
123:   const personStanding: Record<PersonId, number> = {};
124:   const personRegard: Record<PersonId, Readonly<Record<PersonId, number>>> = {};
125:   const personStatus: Record<PersonId, PersonStatus> = {};
126:   const personRanks: Record<PersonId, Readonly<Record<string, PersonRank>>> = {};
127:   for (const p of [...map.world.people].sort((a, b) => strictCompare(a.id, b.id))) {
128:     const stream = createStream(seed, `people/shadow/${p.id}`);
129:     // A fixed order of draws: three stats, then temperament, then public standing.
130:     personTrue[p.id] = {
131:       trueCompetence: drawStat(rules, p.centres.competence, mode, stream),
132:       trueNerve: drawStat(rules, p.centres.nerve, mode, stream),
133:       trueExperience: drawStat(rules, p.centres.experience, mode, stream),
134:       trueBoldness: drawStat(rules, p.temperament.boldness, mode, stream),
135:       trueCandour: drawStat(rules, p.temperament.candour, mode, stream),
136:     };
137:     personStanding[p.id] = drawStat(rules, p.centres.reputation, mode, stream);
138:     personTraits[p.id] = [...new Set(p.traits.map((t) => t.trait))].sort(strictCompare);
139:     const principal = p.faction === null ? undefined : principals.get(p.faction);
140:     const regard = mode === 'unknown-men' ? rules.regardUnknown : regardAtStart(rules, p.regard);
141:     // Regard is stored only where it differs from the pack's regard for the unknown, which every reader falls back to.
142:     const row: Record<PersonId, number> = {};
143:     if (principal !== undefined && principal !== p.id && regard !== rules.regardUnknown) row[principal] = regard;
144:     // Lane 1.5: his cited regard for others (rivals, partners), by the same rule; none in unknown-men.
145:     if (mode !== 'unknown-men') for (const o of p.regardOthers) if (o.toward !== p.id) row[o.toward] = clampSignedPermille(rules.regardPermille[o.direction]);
146:     for (const k of Object.keys(row) as PersonId[]) if (row[k] === rules.regardUnknown) delete row[k];

