81: export function regimentsRaised(rules: RecruitmentRules, asked: number | null, rung: string, loyalty: number | null, askedMen?: number | null): { readonly regiments: number | null; readonly men: number | null; readonly delayDays: number; readonly loyaltyPermille: number } | null {
82:   const row = rules.rungs.find((r) => r.rung === rung);
83:   if (row === undefined) return null;
84:   const factor = rules.loyaltyWeight === 0 || loyalty === null ? 1000 : 1000 - rules.loyaltyWeight + Math.trunc((rules.loyaltyWeight * Math.min(loyalty, rules.loyaltyFull)) / rules.loyaltyFull);
85:   const regiments = asked === null ? null : Math.trunc((Math.trunc((asked * row.sharePermille) / 1000) * factor) / 1000);
86:   if ((askedMen === null || (asked === null && askedMen === undefined)) && row.sharePermille > 0 && factor > 0) return { regiments: null, men: null, delayDays: row.delayDays, loyaltyPermille: factor };
87:   if (askedMen === null || (asked === null && askedMen === undefined)) return { regiments: 0, men: 0, delayDays: row.delayDays, loyaltyPermille: factor };
88:   const men = askedMen === undefined ? regiments! * rules.menPerRegiment : Math.trunc((Math.trunc((askedMen * row.sharePermille) / 1000) * factor) / 1000);
89:   // An explicit headcount can describe a different organization size. Preserve the known nominal quota;
90:   // converting its men by the pack's default again would invent additional regiments. A positive
91:   // sub-regimental remainder has unknown whole-unit count, rather than a fabricated extra regiment.
92:   const nominal = askedMen === undefined || asked !== null ? (men > 0 && regiments === 0 ? null : regiments) : Math.ceil(men / rules.menPerRegiment);
93:   return { regiments: nominal, men, delayDays: row.delayDays, loyaltyPermille: factor };
94: }
