215: export function oversightOf(ctx: TickContext, state: State, person: PersonId, issuer: PersonId): { readonly value: number; readonly terms: readonly OversightTerm[] } {
216:   const rules = ctx.world.rules.people.context;
217:   const base: OversightTerm = { ovKind: 'base', ovValue: rules.oversight };
218:   const side = sideOfPerson(ctx.world.map, state, issuer);
219:   if (side === null || person === issuer) return { value: rules.oversight, terms: [base] };
220:   const from = whereIs(ctx, state, person);
221:   const to = whereIs(ctx, state, issuer);
222:   const courier = routeLatency(ctx.latency, ctx.world.rules.latency, 'courier', from, to, side, null);
223:   if (!courier.ok) return { value: rules.oversightMin, terms: [base, { ovKind: 'floor', ovValue: rules.oversightMin - rules.oversight }] };
224:   // On the wire: a message between them goes by telegraph, quicker than a courier (the wire route, 0026).
225:   const wire = routeLatency(ctx.latency, ctx.world.rules.latency, 'wire', from, to, side, null);
226:   const wired = wire.ok && wire.latency.parts.some((p) => p.part === 'wire');
227:   const terms: OversightTerm[] = [base, { ovKind: 'distance', ovValue: -courier.latency.days * rules.oversightPerCourierDay }];
228:   if (wired) terms.push({ ovKind: 'wire', ovValue: rules.oversightWired });
229:   const raw = terms.reduce((a, x) => a + x.ovValue, 0);
230:   const value = Math.max(rules.oversightMin, Math.min(1000, raw));
231:   if (value > raw) terms.push({ ovKind: 'floor', ovValue: value - raw });
232:   if (value < raw) terms.push({ ovKind: 'ceiling', ovValue: value - raw });
233:   return { value, terms };
234: }
