105: export function credibilityOf(rules: PoliticsRules, state: State, faction: FactionId | null, principal: PersonId | null): { readonly value: number; readonly terms: readonly PoliticsTerm[] } {
106:   const c = rules.credibility;
107:   const terms: PoliticsTerm[] = [{ polKind: 'base', polSubject: null, polValue: c.base }];
108:   if (faction !== null) terms.push({ polKind: 'mandate', polSubject: faction, polValue: scale(mandateOf(rules, state, faction).value, c.mandatePermille) });
109:   if (principal !== null) {
110:     let reliefs = 0;
111:     for (const p of Object.keys(state.personGrievances).sort(strictCompare) as PersonId[]) {
112:       if (state.personGrievances[p]!.some((g) => g.grievanceKind === 'relieved' && g.grievanceAgainst === principal)) reliefs += 1;
113:     }
114:     if (reliefs > 0) terms.push({ polKind: 'reliefs', polSubject: principal, polValue: reliefs * c.perRelief });
115:   }
116:   const raw = terms.reduce((a, t) => a + t.polValue, 0);
117:   const value = Math.max(c.min, Math.min(c.max, raw));
118:   if (value > raw) terms.push({ polKind: 'floor', polSubject: null, polValue: value - raw });
119:   if (value < raw) terms.push({ polKind: 'ceiling', polSubject: null, polValue: value - raw });
120:   return { value, terms };
121: }
